package subprocess

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/MichaelKinsy/PiG/tui"
)

// highlightCode over the host: the lines the host's highlight.js port draws with a palette are the lines Pi's highlightCode returned under that palette
// (test/parity/sdk-vectors/pi-coding-agent/highlightCode.json and getMarkdownTheme.json, generated by running the pinned package).
func piVectorCases(t *testing.T, export string) []struct {
	Name   string
	Args   []json.RawMessage
	Result json.RawMessage
} {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "..", "..", "test", "parity", "sdk-vectors", "pi-coding-agent", export+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var file struct {
		Cases []struct {
			Name   string
			Args   []json.RawMessage
			Result json.RawMessage
		}
	}
	if err := json.Unmarshal(raw, &file); err != nil {
		t.Fatal(err)
	}
	if len(file.Cases) == 0 {
		t.Fatalf("%s has no cases", export)
	}
	return file.Cases
}

func TestHighlightCodeLinesMatchPiUnderThePalette(t *testing.T) {
	// The host's own theme is not the palette's: the lines come out in the palette's colors only when the call carries it.
	previous := tui.ActiveTheme()
	t.Cleanup(func() { tui.SetThemeInstance(previous) })
	for _, c := range piVectorCases(t, "highlightCode") {
		var want struct {
			Palette json.RawMessage
			Lines   []string
		}
		if err := json.Unmarshal(c.Result, &want); err != nil {
			t.Fatal(err)
		}
		var code string
		var lang *string
		if err := json.Unmarshal(c.Args[0], &code); err != nil {
			t.Fatal(err)
		}
		_ = json.Unmarshal(c.Args[1], &lang)
		got, err := HighlightCodeLines(code, derefOrEmpty(lang), false, want.Palette)
		if err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
		if !reflect.DeepEqual(got, want.Lines) {
			t.Errorf("%s: HighlightCodeLines(%q, %v) = %q\nPi %q", c.Name, code, derefOrEmpty(lang), got, want.Lines)
		}
	}
}

func TestMarkdownHighlightCodeLinesMatchPi(t *testing.T) {
	previous := tui.ActiveTheme()
	t.Cleanup(func() { tui.SetThemeInstance(previous) })
	for _, c := range piVectorCases(t, "getMarkdownTheme") {
		var want struct {
			Palette   json.RawMessage
			Highlight []struct {
				Code  string
				Lang  any
				Lines []string
			}
		}
		if err := json.Unmarshal(c.Result, &want); err != nil {
			t.Fatal(err)
		}
		for _, h := range want.Highlight {
			lang, _ := h.Lang.(string)
			got, err := HighlightCodeLines(h.Code, lang, true, want.Palette)
			if err != nil {
				t.Fatalf("%s: %v", c.Name, err)
			}
			if !reflect.DeepEqual(got, h.Lines) {
				t.Errorf("%s: markdown HighlightCodeLines(%q, %q) = %q\nPi %q", c.Name, h.Code, lang, got, h.Lines)
			}
		}
	}
}

func TestHighlightCodeLinesRejectsAPaletteMissingAToken(t *testing.T) {
	if _, err := HighlightCodeLines("x", "javascript", false, []byte(`{"name":"bad","foregrounds":{"accent":"<a>"},"backgrounds":{}}`)); err == nil {
		t.Fatal("a palette without the interface's tokens drew")
	}
}

func derefOrEmpty(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}
